//! The engine's weather ids, as the game names them.
//!
//! The id constants stay in Rust (code refers to them by name), while the id ->
//! name rows live in `data/weather_names.csv`, generated by
//! `tools/gen_weather_names.py` from `include/constants/weather.h`, embedded
//! with `include_str!` and parsed on first use. A short trailing note from the
//! header is kept in the name where the header itself annotates the meaning
//! (fog = terrain).
#![allow(dead_code)]

use std::sync::OnceLock;

const WEATHER_CSV: &str = include_str!("../data/weather_names.csv");

pub fn weather_names() -> &'static [(u16, &'static str)] {
    static T: OnceLock<Vec<(u16, &'static str)>> = OnceLock::new();
    T.get_or_init(|| crate::csv::parse_named("data/weather_names.csv", WEATHER_CSV))
}

pub const WEATHER_NONE: u16 = 0;
pub const WEATHER_SUNNY_CLOUDS: u16 = 1;
pub const WEATHER_SUNNY: u16 = 2;
pub const WEATHER_RAIN: u16 = 3;
pub const WEATHER_SNOW: u16 = 4;
pub const WEATHER_RAIN_THUNDERSTORM: u16 = 5;
pub const WEATHER_FOG_HORIZONTAL: u16 = 6;
pub const WEATHER_VOLCANIC_ASH: u16 = 7;
pub const WEATHER_SANDSTORM: u16 = 8;
pub const WEATHER_FOG_DIAGONAL: u16 = 9;
pub const WEATHER_UNDERWATER: u16 = 10;
pub const WEATHER_SHADE: u16 = 11;
pub const WEATHER_DROUGHT: u16 = 12;
pub const WEATHER_DOWNPOUR: u16 = 13;
pub const WEATHER_UNDERWATER_BUBBLES: u16 = 14;
pub const WEATHER_ABNORMAL: u16 = 15;
pub const WEATHER_LEAVES: u16 = 16;
pub const WEATHER_ROUTE119_CYCLE: u16 = 20;
pub const WEATHER_ROUTE123_CYCLE: u16 = 21;
pub const WEATHER_DEFAULT: u16 = 22;

pub const WEATHER_MISTY_FOG: u16 = 9; // == WEATHER_FOG_DIAGONAL
pub const WEATHER_PSYCHIC_FOG: u16 = 6; // == WEATHER_FOG_HORIZONTAL

pub fn weather_name(id: u16) -> &'static str {
    weather_names()
        .iter()
        .find(|(v, _)| *v == id)
        .map(|(_, n)| *n)
        .unwrap_or("no such weather id in weather.h")
}
